// Compares against NumPy output generated by scripts/gen_reference.py.
// File ref_<N>.bin = float64 LE: input(2N) | fft(2N) | N*ifft = unnormalised inverse(2N), interleaved re/im.
// Skipped when MINIFFTDX_REFDIR is not set (ctest sets it up automatically).
#include <gtest/gtest.h>

#include <cstdlib>
#include <fstream>

#include "reference.hpp"

using namespace minifftdx;
using namespace mfxtest;

namespace {

bool load(unsigned n, std::vector<double>& buf) {
    const char* dir = std::getenv("MINIFFTDX_REFDIR");
    if (!dir) return false;
    std::ifstream f(std::string(dir) + "/ref_" + std::to_string(n) + ".bin", std::ios::binary);
    buf.assign(6 * static_cast<size_t>(n), 0.0);
    f.read(reinterpret_cast<char*>(buf.data()), static_cast<std::streamsize>(buf.size() * sizeof(double)));
    return static_cast<bool>(f);
}

std::vector<cld> as_ref(const double* p, unsigned n) {
    std::vector<cld> v(n);
    for (unsigned i = 0; i < n; ++i) v[i] = cld(p[2 * i], p[2 * i + 1]);
    return v;
}

template <class T, fft_direction D>
void run() {
    for_sizes(
        [&](auto sz) {
            constexpr unsigned N = decltype(sz)::value;
            std::vector<double> buf;
            ASSERT_TRUE(load(N, buf)) << "missing/short reference file for N=" << N;
            std::vector<complex<T>> x(N), y(N);
            for (unsigned i = 0; i < N; ++i) x[i] = {static_cast<T>(buf[2 * i]), static_cast<T>(buf[2 * i + 1])};
            using Desc = fft_descriptor<Size<N>, Precision<T>, Direction<D>>;
            // The input is exactly representable in float, so numpy's float64 result is the truth.
            cpu::execute<Desc>(x.data(), y.data(), 1);
            const double* expect = buf.data() + (D == fft_direction::forward ? 2 * N : 4 * N);
            const Stats s = compare<T>(y, as_ref(expect, N));
            rows().push_back({"numpy", std::is_same<T, float>::value ? "float" : "double",
                              D == fft_direction::forward ? "forward" : "inverse", N, s});
            EXPECT_LT(s.rel_l2, rel_error_bound<T>(Desc::log2_size)) << "N=" << N;
        },
        AllSizes{});
}

}  // namespace

#define SKIP_IF_NO_REF() if (!std::getenv("MINIFFTDX_REFDIR")) GTEST_SKIP() << "MINIFFTDX_REFDIR not set"

TEST(NumpyReference, FloatForward) { SKIP_IF_NO_REF(); run<float, fft_direction::forward>(); }
TEST(NumpyReference, FloatInverse) { SKIP_IF_NO_REF(); run<float, fft_direction::inverse>(); }
TEST(NumpyReference, DoubleForward) { SKIP_IF_NO_REF(); run<double, fft_direction::forward>(); }
TEST(NumpyReference, DoubleInverse) { SKIP_IF_NO_REF(); run<double, fft_direction::inverse>(); }
